def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            try:
                return int(obj[0]), int(obj[1])
            except:
                return default
        return default

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def step_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    def clamp_move(m):
        dx = m[0] if isinstance(m, (list, tuple)) and len(m) > 0 else 0
        dy = m[1] if isinstance(m, (list, tuple)) and len(m) > 1 else 0
        dx = -1 if dx < -1 else (1 if dx > 1 else int(dx))
        dy = -1 if dy < -1 else (1 if dy > 1 else int(dy))
        return [dx, dy]

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position", (0, 0)))
    opp_pos = pos(observation.get("opponent_position", self_pos))
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        best = corners[0]
        best_score = None
        for c in corners:
            score = md(c, opp_pos) - md(c, self_pos)
            if best_score is None or score > best_score:
                best_score = score
                best = c
        return step_toward(self_pos, best)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        best = None
        best_score = None
        for t in targets:
            tp = pos(t, None)
            if tp is None:
                continue
            score = -md(self_pos, tp)
            if best is None or score > best_score:
                best = tp
                best_score = score
        if best is not None:
            return step_toward(self_pos, best)

        # fallback: move toward opponent territory implied by enemy position
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    best = None
    best_score = None
    for r in resources:
        rp = pos(r, None)
        if rp is None:
            continue
        # prefer closer resources, but slightly prefer ones farther from opponent
        score = -md(self_pos, rp) + 0.25 * md(opp_pos, rp)
        if best is None or score > best_score:
            best = rp
            best_score = score
    if best is not None:
        return step_toward(self_pos, best)

    # Denial / fallback: pressure opponent or move away if already adjacent
    if md(self_pos, opp_pos) <= 1:
        return step_away(self_pos, opp_pos)
    return step_toward(self_pos, opp_pos)

